#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int to, rev;
    long long cap;
    int cst;
    Edge(int to, int rev, long long cap, int cst) : to(to), rev(rev), cap(cap), cst(cst) {}
};

struct MCF {
    int size;
    std::vector<std::vector<Edge>> adj;
    std::vector<std::pair<int, int>> edges;
    std::vector<int> potential, prev_node, prev_edge;
    std::vector<bool> visited;

    MCF(int size) : size(size), adj(size), potential(size), prev_node(size), prev_edge(size), visited(size) {}

    int add_edge(int u, int v, long long cap, int cst) {
        int index = (int)edges.size();
        edges.emplace_back(u, (int)adj[u].size());
        adj[u].emplace_back(v, (int)adj[v].size(), cap, cst);
        adj[v].emplace_back(u, (int)adj[u].size() - 1, 0, -cst);
        return index;
    }

    Edge get_edge(int i) {
        auto &e = adj[edges[i].first][edges[i].second];
        auto &re = adj[e.to][e.rev];
        return Edge(edges[i].first, e.to, e.cap + re.cap, e.cst);
    }

    std::vector<Edge> all_edges() {
        std::vector<Edge> res;
        for (int i = 0; i < (int)edges.size(); ++i) {
            auto &e = adj[edges[i].first][edges[i].second];
            auto &re = adj[e.to][e.rev];
            res.emplace_back(edges[i].first, e.to, e.cap + re.cap, e.cst);
        }
        return res;
    }

    bool dijkstra(int s, int t) {
        std::fill(potential.begin(), potential.end(), 0);
        std::fill(visited.begin(), visited.end(), false);
        std::vector<long long> dist(size, LLONG_MAX);
        std::priority_queue<std::pair<long long, int>, std::vector<std::pair<long long, int>>, std::greater<>> pq;
        dist[s] = 0;
        pq.emplace(0, s);
        while (!pq.empty()) {
            auto [d, v] = pq.top(); pq.pop();
            if (visited[v]) continue;
            visited[v] = true;
            if (v == t) break;
            for (int i = 0; i < (int)adj[v].size(); ++i) {
                auto &e = adj[v][i];
                if (e.cap == 0 || visited[e.to]) continue;
                long long nd = d + e.cst;
                if (dist[e.to] > nd) {
                    dist[e.to] = nd;
                    prev_node[e.to] = v;
                    prev_edge[e.to] = i;
                    pq.emplace(nd, e.to);
                }
            }
        }
        if (!visited[t]) return false;
        for (int v = 0; v < size; ++v) {
            if (visited[v]) {
                potential[v] -= dist[t];
            }
        }
        return true;
    }

    std::vector<std::pair<long long, long long>> min_cost_flow(int s, int t, long long max_flow = (1LL << 32) - 1) {
        long long flow = 0;
        long long total_cost = 0;
        std::vector<std::pair<long long, long long>> results;
        results.emplace_back(flow, total_cost);
        while (flow < max_flow) {
            if (!dijkstra(s, t)) break;
            long long c = max_flow - flow;
            int v = t;
            while (v != s) {
                int u = prev_node[v];
                auto &e = adj[u][prev_edge[v]];
                c = std::min(c, e.cap);
                v = u;
            }
            v = t;
            while (v != s) {
                int u = prev_node[v];
                auto &e = adj[u][prev_edge[v]];
                e.cap -= c;
                adj[v][e.rev].cap += c;
                v = u;
            }
            long long delta = -potential[s];
            flow += c;
            total_cost += c * delta;
            if (results.back().second == total_cost) results.pop_back();
            results.emplace_back(flow, total_cost);
        }
        return results;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    int a1, a2, a3;
    cin >> a1 >> a2 >> a3;
    int b1, b2, b3;
    cin >> b1 >> b2 >> b3;

    MCF g(8);
    g.add_edge(0, 1, a1, 0);
    g.add_edge(0, 2, a2, 0);
    g.add_edge(0, 3, a3, 0);
    g.add_edge(4, 7, b1, 0);
    g.add_edge(5, 7, b2, 0);
    g.add_edge(6, 7, b3, 0);

    for (int i = 1; i <= 3; ++i) {
        for (int j = 4; j <= 6; ++j) {
            int cst = ((j - i) % 3 == 1) ? 1 : 0;
            g.add_edge(i, j, LLONG_MAX, cst);
        }
    }

    auto res = g.min_cost_flow(0, 7);
    long long ans1 = res.back().first;
    long long ans2 = min(a1, b2) + min(a2, b3) + min(a3, b1);
    cout << ans1 << " " << ans2 << "\n";

    return 0;
}

